item.aggregated_output:
 1	air 0.1;
 2	program user_service;
 3	requires {
 4	  capability air:http/server@1 digest "sha256:9d8f75ab79c9a2fc51c2cfa1aa42d946741b7fcac462b1767e607bf1018879b6" signed-by "air:foundation";
 5	  capability air:json@1 digest "sha256:f276fd0e2abf43cd700d17ac7d5255969821283e5f2f184dd59f1d1bb6685a14" signed-by "air:foundation";
 6	  capability air:sqlite/users.insert@1 digest "sha256:b5a70c72dc2df26dd59e7508fcd06e828b89dfb1f2c6b318d5eb713be826d131" signed-by "air:foundation";
 7	}
 8	
 9	record UserInput {
10	  name string;
11	  email string;
12	}
13	
14	record UserOutput {
15	  id i64;
16	}
17	
18	error UserError {
19	  invalid_json;
20	  invalid_name;
21	  invalid_email;
22	  duplicate_email;
23	  storage_failure;
24	}
25	
26	fn create_user input UserInput returns UserOutput errors UserError;
